import{Ct as e,ct as t,lt as n,q as r}from"./chunks/framework.BVmwMUcr.js";var i=JSON.parse(`{"title":"Nearby","description":"An overview of places near SCUT University Town Campus","frontmatter":{"lang":"en-US","title":"Nearby","description":"An overview of places near SCUT University Town Campus","llm_translated":true},"headers":[],"relativePath":"en/infra/hemc/nearby.md","filePath":"en/infra/hemc/nearby.md","lastUpdated":1791510705000}`),a={name:`en/infra/hemc/nearby.md`};function o(r,i,a,o,s,c){return e(),t(`div`,null,[...i[0]||=[n(`<div style="display:none;" hidden="true" aria-hidden="true" data-nosnippet>Are you an LLM? You can read better optimized documentation at /en/infra/hemc/nearby.md for this page in Markdown format</div><h1 id="around-university-town-campus" tabindex="-1">Around University Town Campus <a class="header-anchor" href="#around-university-town-campus" aria-label="Permalink to “Around University Town Campus”">​</a></h1><p>The main places to eat, drink, and have fun around University Town Campus are concentrated in four urban villages: <strong>Nanting, Beiting, Beigang, and Suishi</strong>. Among them, gogo New World (gogo 新天地) in Beigang Village is the most-visited shopping complex in University Town.</p><h2 id="dining-night-markets" tabindex="-1">Dining &amp; Night Markets <a class="header-anchor" href="#dining-night-markets" aria-label="Permalink to “Dining &amp; Night Markets”">​</a></h2><h3 id="beigang-village-gogo-new-world-gogo-新天地" tabindex="-1">Beigang Village &amp; gogo New World (gogo 新天地) <a class="header-anchor" href="#beigang-village-gogo-new-world-gogo-新天地" aria-label="Permalink to “Beigang Village &amp; gogo New World (gogo 新天地)”">​</a></h3><p>About 15 minutes on foot from Area C gets you to gogo New World. It has common chain restaurant brands such as KFC, McDonald&#39;s, and Saizeriya, plus milk tea shops like Yidiandian and HEYTEA.</p><h3 id="suishi-village" tabindex="-1">Suishi Village <a class="header-anchor" href="#suishi-village" aria-label="Permalink to “Suishi Village”">​</a></h3><p>Suishi Village is the closest to campus — walk straight along the road between the Library and the A1 teaching building for about 3 minutes and you reach it right outside the school gate. Main dining options:</p><ul><li><strong>Noodles/rice</strong>: Zhenya Beef Noodles, Longjiang Pork Knuckle Rice</li><li><strong>Full meals/group dinners</strong>: Beidiaor&#39;er Copper Pot Chicken, Northeastern Chinese food, Wuhan stir-fry, Xianmiao Roast Chicken, chicken pot (jigongbao)</li><li><strong>Drinks</strong>: Mixue, ChaPanda, Lucky Cup</li><li>(Suggestions for more shops are welcome)</li></ul><blockquote><p>gogo New World and Suishi Village each have their own strengths: the former concentrates brand chains and suits shopping trips and group dinners; the latter wins on proximity to campus and variety, making it a great spot for everyday meals out and late-night snacks.</p></blockquote><h2 id="daily-shopping-supermarkets" tabindex="-1">Daily Shopping &amp; Supermarkets <a class="header-anchor" href="#daily-shopping-supermarkets" aria-label="Permalink to “Daily Shopping &amp; Supermarkets”">​</a></h2><h3 id="on-campus" tabindex="-1">On Campus <a class="header-anchor" href="#on-campus" aria-label="Permalink to “On Campus”">​</a></h3><ul><li><strong>Xiya Xing&#39;an Comprehensive Supermarket</strong>: located in the campus living area; the first floor focuses on food and drinks, while the second floor has food, stationery, and a small number of eateries. Not large, but it covers most everyday necessities and snacks.</li><li><strong>FamilyMart</strong>: downstairs in C10 (behind McDonald&#39;s).</li><li><strong>Fruit shop below C10</strong>: one option for buying fruit on campus.</li></ul><h3 id="off-campus" tabindex="-1">Off Campus <a class="header-anchor" href="#off-campus" aria-label="Permalink to “Off Campus”">​</a></h3><ul><li><strong>Suishi Village fruit shop</strong>: close by and within walking distance — the most convenient choice for buying fruit off campus.</li></ul><blockquote><p>There is no wet market near University Town Campus. If you need to buy groceries and cook, consider online fresh-grocery delivery or a large supermarket nearby.</p></blockquote><h2 id="rentals-short-term-housing" tabindex="-1">Rentals &amp; Short-Term Housing <a class="header-anchor" href="#rentals-short-term-housing" aria-label="Permalink to “Rentals &amp; Short-Term Housing”">​</a></h2><p>The urban villages around University Town Campus (Nanting, Beiting, Beigang, and Suishi) all have rooms available for rent, suitable for postgraduate exam preparation, internships, and other situations that call for short- or long-term housing.</p><blockquote><p>Contributions are welcome from students with relevant experience on rental details (comparisons of common areas, rent levels, landlords, scam-avoidance tips, etc.).</p></blockquote><h2 id="transit-connections" tabindex="-1">Transit Connections <a class="header-anchor" href="#transit-connections" aria-label="Permalink to “Transit Connections”">​</a></h2><h3 id="metro" tabindex="-1">Metro <a class="header-anchor" href="#metro" aria-label="Permalink to “Metro”">​</a></h3><p>Exit the living area through <strong>West Gate 1</strong>, turn left, and cross the road at the traffic lights to reach <strong>University Town South Station</strong> — very convenient. You can transfer to the following lines:</p><ul><li><strong>Line 7</strong>: reaches Guangzhou South Station and commercial hubs such as Nancun Wanbo and Hanxi Changlong</li><li><strong>Line 4</strong>: reaches Wanshengwei Station (transfer to Line 8)</li><li><strong>Line 12</strong>: reaches places on the island and in Haizhu District</li></ul><h3 id="shared-bikes" tabindex="-1">Shared Bikes <a class="header-anchor" href="#shared-bikes" aria-label="Permalink to “Shared Bikes”">​</a></h3><p>Only <strong>shared bikes</strong> are available on campus; <strong>e-bikes are not allowed</strong>, and there is no shared e-bike service either. The Hello and Qingju shared bikes on campus can be ridden off campus (they are not campus-exclusive bikes), making them suitable for rides to the metro station or anywhere around University Town.</p><h3 id="leaving-the-island" tabindex="-1">Leaving the Island <a class="header-anchor" href="#leaving-the-island" aria-label="Permalink to “Leaving the Island”">​</a></h3><p>Taking the metro (Line 7, Line 4, or Line 12) is the most convenient way off the island. A few bus routes also cross Pazhou Bridge, the Jinguang Tunnel, and similar links to the mainland; for specific routes and service status, follow announcements from the Guangzhou Bus Group.</p><h2 id="leisure-entertainment" tabindex="-1">Leisure &amp; Entertainment <a class="header-anchor" href="#leisure-entertainment" aria-label="Permalink to “Leisure &amp; Entertainment”">​</a></h2><ul><li><strong>gogo New World (gogo 新天地)</strong>: the most complete shopping complex in University Town; besides dining it has a cinema, KTV, clothing stores, and more — the first choice for group dinners, shopping, and movies.</li><li><strong>Gyms</strong>: the University Town Sports Center has a gym you can use; there is also a gym on the third floor of the Xiya Xing&#39;an Comprehensive Supermarket on campus — look into it for details.</li><li><strong>Central Lake Park</strong>: an outdoor spot on Xiaoguwei Island, good for daytime and weekend outings. <strong>Safety reminder</strong>: go with others; in particular, avoid jogging on the inner ring road or strolling in Central Lake Park at night, and stay safe.</li></ul>`,29)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};